import re, json, subprocess
norm = lambda s: re.sub(r'\s+', ' ', s).strip()
paths = subprocess.run(['/Users/kevinbarnard/.dprint/bin/dprint','output-file-paths'],
                       capture_output=True, text=True).stdout.split()
before = {}
for p in paths:
